# Surah Al-An'am (chapter 6) — part 14: ayat 134-143 (IDs 923-932)
SURAH = 6

ENTRIES = {
923: (
"بے شک — جس کا — تم سے — وعدہ کیا جاتا ہے — ضرور آئے گا — اور تم — عاجز نہیں کر سکتے",
"""۱۔ قیامت — آنے والی ہے — کوئی ٹال نہیں سکتا۔
۲۔ ’’إِنَّ مَا تُوعَدُونَ لَآتٍ وَمَا أَنتُم بِمُعْجِزِينَ‘‘ — بے شک — جس کا — تم سے — وعدہ کیا جاتا ہے — ضرور آئے گا — اور تم — عاجز نہیں کر سکتے — یعنی قیامت — ٹلنے والی نہیں — کوئی اسے نہیں روک سکتا۔
۳۔ عملی سبق: آخرت کی تیاری کرو؛ کوئی ٹال نہیں سکے گا۔"""
),
924: (
"کہہ دیں: اے میری قوم! — تم اپنے مقام پر عمل کرو — میں بھی عمل کرتا ہوں — پس — عنقریب — تم جان جاؤ گے کہ — اس — گھر کا اچھا انجام کس کا ہے — بے شک ظالم فلاح نہیں پائیں گے",
"""۱۔ نبی ﷺ کا حکم — تم اپنا راستہ چلو۔
۲۔ ’’قُلْ يَا قَوْمِ اعْمَلُوا عَلَىٰ مَكَانَتِكُمْ إِنِّي عَامِلٌ‘‘ — کہہ دیں: اے میری قوم! — تم اپنے مقام پر عمل کرو — میں بھی عمل کرتا ہوں — یعنی نبی ﷺ نے بھی اپنا راستہ اپنایا۔
۳۔ ’’فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُ عَاقِبَۃُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ‘‘ — پس — عنقریب — تم جان جاؤ گے کہ — اس — گھر کا اچھا انجام کس کا ہے — بے شک ظالم فلاح نہیں پائیں گے — یعنی آخرت — کا معاملہ انجام میں واضح ہو جائے گا۔
۴۔ عملی سبق: آخری انجام — اچھے اعمال کا ہوتا ہے؛ ظالم — کبھی فلاح نہیں پاتے۔"""
),
925: (
"اور انہوں نے — اللہ کے لیے — اس میں سے جو اس نے پیدا کیا — فصلوں اور چوپایوں میں سے — ایک حصہ — رکھا — پس وہ اپنے زعم (قیاس) کے مطابق کہتے ہیں: یہ اللہ کے لیے ہے اور یہ ہمارے — شریکوں — کے لیے — پس — جو — ان — کے شریکوں — کا حصہ ہے وہ اللہ تک نہیں پہنچتا — اور — جو — اللہ کا حصہ ہے وہ — ان — کے شریکوں تک پہنچتا ہے — برا ہے جو وہ فیصلہ کرتے ہیں",
"""۱۔ جاہلیت کی تقسیم — اللہ اور شریکوں کے درمیان۔
۲۔ ’’وَجَعَلُوا لِلّٰہِ مِمَّا ذَرَأَ مِنَ الْحَرْثِ وَالْأَنْعَامِ نَصِيبًا فَقَالُوا هَٰذَا لِلّٰہِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَائِنَا‘‘ — اور انہوں نے — اللہ کے لیے — اس میں سے جو اس نے پیدا کیا — فصلوں اور چوپایوں میں سے — ایک حصہ — رکھا — پس وہ اپنے زعم (قیاس) کے مطابق کہتے ہیں: یہ اللہ کے لیے ہے اور یہ ہمارے — شریکوں — کے لیے — یعنی جاہلیت میں — خود ساختہ تقسیم۔
۳۔ ’’فَمَا كَانَ لِشُرَكَائِهِمْ فَلَا يَصِلُ إِلَى اللّٰہِ وَمَا كَانَ لِلّٰہِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَائِهِمْ سَاءَ مَا يَحْكُمُونَ‘‘ — پس — جو — ان — کے شریکوں — کا حصہ ہے وہ اللہ تک نہیں پہنچتا — اور — جو — اللہ کا حصہ ہے وہ — ان — کے شریکوں تک پہنچتا ہے — برا ہے جو وہ فیصلہ کرتے ہیں — یعنی تقسیم بے انصافی پر مبنی ہے — یہ ایک شرک ہے۔
۴۔ عملی سبق: اللہ کی دی ہوئی چیزوں کا صحیح مصرف اختیار کرو؛ خود ساختہ رسوم — سے بچو۔"""
),
926: (
"اور اسی طرح — ان — کے — شریکوں نے — بہت سے مشرکوں کے لیے — ان کی اولاد کے — قتل — کو مزین کر دیا — تاکہ — وہ — انہیں — ہلاک کریں — اور ان پر ان کا دین — بھٹکا — دیں — اور اگر اللہ چاہتا تو وہ ایسا نہیں کرتے — پس — انہیں — چھوڑو — جو وہ گھڑتے ہیں",
"""۱۔ شرک نے — اولاد کے قتل — کو خوبصورتی دی۔
۲۔ ’’وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ الْمُشْرِكِينَ قَتْلَ أَوْلَادِهِمْ شُرَكَاؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا عَلَيْهِمْ دِينَهُمْ‘‘ — اور اسی طرح — ان — کے — شریکوں نے — بہت سے مشرکوں کے لیے — ان کی اولاد کے — قتل — کو مزین کر دیا — تاکہ — وہ — انہیں — ہلاک کریں — اور ان پر ان کا دین — بھٹکا — دیں — یعنی جاہلیت میں بیٹیوں کو زندہ دفن کرنا شرک کی سنت تھی۔
۳۔ ’’وَلَوْ شَاءَ اللّٰہُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ‘‘ — اور اگر اللہ چاہتا تو وہ ایسا نہیں کرتے — پس — انہیں — چھوڑو — جو وہ گھڑتے ہیں — یعنی اللہ نے — انسان — کو اختیار دیا — تو گمراہ — اپنی روش پر رہتے ہیں۔
۴۔ عملی سبق: بچوں کو — نقصان — مت پہنچاؤ؛ شرک — جڑ ہے؛ اللہ سے ہدایت مانگو۔"""
),
927: (
"اور انہوں نے کہا: یہ چوپائے اور فصلیں — حرام (محفوظ) — ہیں — انہیں — کوئی — نہیں کھاتا — سوائے جس کو ہم چاہیں — اپنے زعم کے مطابق — اور چوپائے — جن کی پیٹھ — حرام — کی گئی — اور چوپائے — جن پر اللہ کا نام — نہیں لیتے — اللہ پر جھوٹ گھڑتے ہوئے — عنقریب — وہ — ان — کو — بدلہ دے گا — جو وہ گھڑتے تھے",
"""۱۔ جاہلیت کے — حرام کردہ چوپائے — خود ساختہ۔
۲۔ ’’وَقَالُوا هَٰذِهِ أَنْعَامٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَا إِلَّا مَن نَّشَاءُ بِزَعْمِهِمْ‘‘ — اور انہوں نے کہا: یہ چوپائے اور فصلیں — حرام (محفوظ) — ہیں — انہیں — کوئی — نہیں کھاتا — سوائے جس کو ہم چاہیں — اپنے زعم کے مطابق — یعنی ان کی خود ساختہ تقدیس۔
۳۔ ’’وَأَنْعَامٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَامٌ لَّا يَذْكُرُونَ اسْمَ اللّٰہِ عَلَيْهَا افْتِرَاءً عَلَيْهِ‘‘ — اور چوپائے — جن کی پیٹھ — حرام — کی گئی — اور چوپائے — جن پر اللہ کا نام — نہیں لیتے — اللہ پر جھوٹ گھڑتے ہوئے — یعنی اللہ کے نام — بغیر — ذبیحہ اور حرام کردہ پیٹھیں — سب جھوٹ ہے۔
۴۔ ’’سَيَجْزِيهِم بِمَا كَانُوا يَفْتَرُونَ‘‘ — عنقریب — وہ — ان — کو — بدلہ دے گا — جو وہ گھڑتے تھے — یعنی خود ساختہ حرام کا — بدلہ — خود ساکتہ گھڑنے — والے کو ملے گا۔
۵۔ عملی سبق: خود ساختہ حرام — مت گھڑو؛ اللہ کے — حکم — کی پیروی کرو۔"""
),
928: (
"اور انہوں نے کہا: جو کچھ ان چوپایوں کے پیٹ میں ہے — وہ — ہمارے — مردوں کے لیے خاص ہے اور ہماری بیویوں پر حرام ہے — اور اگر وہ مردہ ہو تو وہ سب — اس — میں — شریک ہیں — عنقریب — وہ — ان — کو — بدلہ دے گا — ان کے بیان (وصف) کے مطابق — بے شک وہ — حکمت والا — جاننے والا ہے",
"""۱۔ جاہلیت کی — خود ساختہ — تقسیم: مرد فائدہ، عورت سے منع۔
۲۔ ’’وَقَالُوا مَا فِي بُطُونِ هَٰذِهِ الْأَنْعَامِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰ أَزْوَاجِنَا‘‘ — اور انہوں نے کہا: جو کچھ ان چوپایوں کے پیٹ میں ہے — وہ — ہمارے — مردوں کے لیے خاص ہے اور ہماری بیویوں پر حرام ہے — یعنی ان کی ناقص عقل کی تقسیم۔
۳۔ ’’وَإِن يَكُن مَّيْتَۃً فَهُمْ فِيهِ شُرَكَاءُ‘‘ — اور اگر وہ مردہ ہو تو وہ سب — اس — میں — شریک ہیں — یعنی مردہ ہونے پر — سب کو حصہ ملتا — عجیب — تضاد — تھا۔
۴۔ ’’سَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُ حَكِيمٌ عَلِيمٌ‘‘ — عنقریب — وہ — ان — کو — بدلہ دے گا — ان کے بیان (وصف) کے مطابق — بے شک وہ — حکمت والا — جاننے والا ہے — یعنی اللہ ان کی بے بنیاد تقسیم کا بدلہ دے گا۔
۵۔ عملی سبق: ناقص — خود ساختہ تقسیم — سے بچو؛ انصاف — اختیار کرو۔"""
),
929: (
"وہ — یقینی — ہار گئے جنہوں نے اپنی اولاد کو — بیوقوفی (سفہا) — سے بغیر علم کے قتل کیا — اور — اللہ کے — دیے ہوئے رزق کو — حرام کر لیا — اللہ پر جھوٹ گھڑتے ہوئے — وہ — یقیناً — گمراہ ہو گئے — اور — وہ — ہدایت یافتہ — نہ رہے",
"""۱۔ اولاد کا قتل — سب سے بڑی ہلاکت۔
۲۔ ’’قَدْ خَسِرَ الَّذِينَ قَتَلُوا أَوْلَادَهُمْ سَفَهًا بِغَيْرِ عِلْمٍ وَحَرَّمُوا مَا رَزَقَهُمُ اللّٰہُ افْتِرَاءً عَلَى اللّٰہِ‘‘ — وہ — یقینی — ہار گئے جنہوں نے اپنی اولاد کو — بیوقوفی (سفہا) — سے بغیر علم کے قتل کیا — اور — اللہ کے — دیے ہوئے رزق کو — حرام کر لیا — اللہ پر جھوٹ گھڑتے ہوئے — یعنی یہ سب — بیوقوفی — اور جھوٹ — پر — مبنی تھا۔
۳۔ ’’قَدْ ضَلُّوا وَمَا كَانُوا مُهْتَدِينَ‘‘ — وہ — یقیناً — گمراہ ہو گئے — اور — وہ — ہدایت یافتہ — نہ رہے — یعنی یہی ان کا انجام — ہے۔
۴۔ عملی سبق: اولاد کو — کبھی — نقصان مت پہنچاؤ؛ اللہ کے رزق کو حرام مت کرو۔"""
),
930: (
"اور وہی — ہے جس نے — باغ — بنائے — ٹہنیوں والے اور بغیر ٹہنیوں والے — اور کھجور — اور — کھیتی — جس کے کھانے — مختلف — ہیں — اور زیتون — اور انار — آپس میں ملتے جلتے اور الگ الگ — کھاؤ — اس — کے — پھل — کو — جب — وہ — پھل — دے — اور — اس — کا حق — اس — کی — کٹائی — کے دن — ادا کرو — اور اسراف نہ کرو — بے شک وہ — فضول خرچ کرنے والوں سے محبت نہیں کرتا",
"""۱۔ اللہ نے باغ — کھیتی — سب بنائے۔
۲۔ ’’وَهُوَ الَّذِي أَنشَأَ جَنَّاتٍ مَّعْرُوشَاتٍ وَغَيْرَ مَعْرُوشَاتٍ وَالنَّخْلَ وَالزَّرْعَ مُخْتَلِفًا أُكُلُهُ‘‘ — اور وہی — ہے جس نے — باغ — بنائے — ٹہنیوں والے اور بغیر ٹہنیوں والے — اور کھجور — اور — کھیتی — جس کے کھانے — مختلف — ہیں — یعنی ہر — پیداوار — اللہ کی طرف سے ہے۔
۳۔ ’’وَالزَّيْتُونَ وَالرُّمَّانَ مُتَشَابِهًا وَغَيْرَ مُتَشَابِهٍ كُلُوا مِن ثَمَرِهِ إِذَا أَثْمَرَ وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ‘‘ — اور زیتون — اور انار — آپس میں ملتے جلتے اور الگ الگ — کھاؤ — اس — کے — پھل — کو — جب — وہ — پھل — دے — اور — اس — کا حق — اس — کی — کٹائی — کے دن — ادا کرو — یعنی کٹائی کے دن — زکوٰۃ / حق — دینا فرض ہے۔
۴۔ ’’وَلَا تُسْرِفُوا إِنَّهُ لَا يُحِبُّ الْمُسْرِفِينَ‘‘ — اور اسراف نہ کرو — بے شک وہ — فضول خرچ کرنے والوں سے محبت نہیں کرتا — یعنی اصراف سے بچو۔
۵۔ عملی سبق: کٹائی — کے دن — حق (زکوٰۃ) ادا کرو؛ اسراف مت کرو۔"""
),
931: (
"اور چوپایوں میں سے — کچھ — اٹھانے والے — اور کچھ — نرم و نازک — کھاؤ — اس — میں سے جو اللہ نے تمہیں رزق دیا — اور شیطان کے — قدموں — کی پیروی مت کرو — بے شک وہ — تمہارا — واضح دشمن ہے",
"""۱۔ چوپایوں میں سے — کچھ بھاری بھر کم (بوجھ اٹھانے والے) اور کچھ نرم و نازک (کھانے کے لیے)۔
۲۔ ’’وَمِنَ الْأَنْعَامِ حَمُولَۃً وَفَرْشًا كُلُوا مِمَّا رَزَقَكُمُ اللّٰہُ وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ‘‘ — اور چوپایوں میں سے — کچھ — اٹھانے والے — اور کچھ — نرم و نازک — کھاؤ — اس — میں سے جو اللہ نے تمہیں رزق دیا — اور شیطان کے — قدموں — کی پیروی مت کرو — یعنی اللہ کے رزق کو — حلال — سمجھو؛ شیطان کی اطاعت مت کرو۔
۳۔ ’’إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ‘‘ — بے شک وہ — تمہارا — واضح دشمن ہے — یعنی شیطان — واضح دشمن ہے۔
۴۔ عملی سبق: اللہ کا رزق حلال سمجھو؛ شیطان سے بچو۔"""
),
932: (
"آٹھ — جوڑے (اقسام) — بھیڑ کی دو — اور بکری کی دو — کہہ دیں: کیا اس نے — دونوں — نر — حرام کیے ہیں — یا دونوں مادہ — یا — ان — کے — پیٹوں میں کیا ہے — ان — کو — مجھے — علم — سے — بتاؤ — اگر تم سچے ہو",
"""۱۔ آٹھ — اقسام — کی وضاحت۔
۲۔ ’’ثَمَانِيَۃَ أَزْوَاجٍ مِّنَ الضَّأْنِ اثْنَيْنِ وَمِنَ الْمَعْزِ اثْنَيْنِ‘‘ — آٹھ — جوڑے (اقسام) — بھیڑ کی دو — اور بکری کی دو — یعنی — چار — قسم — بھیڑ اور بکری — دو دو (نر مادہ)۔
۳۔ ’’قُلْ آلذَّكَرَيْنِ حَرَّمَ أَمِ الْأُنثَيَيْنِ أَمَّا اشْتَمَلَتْ عَلَيْهِ أَرْحَامُ الْأُنثَيَيْنِ نَبِّئُونِي بِعِلْمٍ إِن كُنتُمْ صَادِقِينَ‘‘ — کہہ دیں: کیا اس نے — دونوں — نر — حرام کیے ہیں — یا دونوں مادہ — یا — ان — کے — پیٹوں میں کیا ہے — ان — کو — مجھے — علم — سے — بتاؤ — اگر تم سچے ہو — یعنی اللہ نے — ان — کو — حرام نہیں کیا — ان کی بات — بے بنیاد ہے — سوال: دلیل دو۔
۴۔ عملی سبق: بے دلیل — خود ساختہ حرام — سے بچو؛ علم — کی پیروی کرو۔"""
),
}
